当前函数就是：
```ts
type Row = { month: string; actual: number | null; plan: number };
function toPoints(rows: Row[]) {
  return rows.map(({ month, actual, plan }) => ({ month, actual: actual ?? 0, plan, delta: (actual ?? 0) - plan }));
}
```

